import{_ as l,o as e,c as t,a2 as o}from"./chunks/framework.A5mep7Fe.js";const p=JSON.parse('{"title":"📚 04 · 刷题与学习资源","description":"","frontmatter":{},"headers":[],"relativePath":"10-职业发展与资源/04-刷题与学习资源.md","filePath":"10-职业发展与资源/04-刷题与学习资源.md","lastUpdated":1786806808000}'),i={name:"10-职业发展与资源/04-刷题与学习资源.md"};function r(n,a,s,h,d,u){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="📚-04-·-刷题与学习资源" tabindex="-1">📚 04 · 刷题与学习资源 <a class="header-anchor" href="#📚-04-·-刷题与学习资源" aria-label="Permalink to &quot;📚 04 · 刷题与学习资源&quot;">​</a></h1><blockquote><p>把前面的知识「练熟」。本篇汇总题库、课程、论文、博客、开源（社区共识，按自己节奏挑选，别贪多）。</p></blockquote><hr><h2 id="一、代码刷题" tabindex="-1">一、代码刷题 <a class="header-anchor" href="#一、代码刷题" aria-label="Permalink to &quot;一、代码刷题&quot;">​</a></h2><ul><li><strong>LeetCode</strong>：中等为主（数组/链表/树/DP/图/堆），AI 岗也要刷</li><li><strong>牛客网</strong>：国内笔面经、剑指 Offer</li><li><strong>Codeforces / AtCoder</strong>：算法竞赛练手（研究岗加分）</li><li>策略：按题型刷 + 限时模拟 + 复盘错题</li></ul><h2 id="二、课程-系统学习" tabindex="-1">二、课程（系统学习） <a class="header-anchor" href="#二、课程-系统学习" aria-label="Permalink to &quot;二、课程（系统学习）&quot;">​</a></h2><ul><li><strong>深度学习</strong>：吴恩达 DL Specialization、李宏毅 ML/DL（中文友好）</li><li><strong>LLM/Transformer</strong>：Stanford CS336（大模型）、李宏毅生成式</li><li><strong>RL</strong>：David Silver 强化学习、OpenAI Spinning Up</li><li><strong>系统/工程</strong>：MIT 6.824（分布式）、CS 系统课</li><li>平台：Coursera / B 站 / 油管（官方 lecture）</li></ul><h2 id="三、论文-跟前沿" tabindex="-1">三、论文（跟前沿） <a class="header-anchor" href="#三、论文-跟前沿" aria-label="Permalink to &quot;三、论文（跟前沿）&quot;">​</a></h2><ul><li><strong>必读经典</strong>：Attention Is All You Need、BERT、GPT 系列、LLaMA、RoPE、LoRA、RLHF(InstructGPT)、DPO、Diffusion(DDPM)、Stable Diffusion</li><li><strong>追踪</strong>：arXiv（cs.CL/cv/LG）、NeurIPS/ICML/ICLR/CVPR/ACL 录用</li><li>读法：摘要→图→方法→实验，先懂思想再抠细节</li></ul><h2 id="四、博客与资讯" tabindex="-1">四、博客与资讯 <a class="header-anchor" href="#四、博客与资讯" aria-label="Permalink to &quot;四、博客与资讯&quot;">​</a></h2><ul><li>公司技术博客（OpenAI/Google DeepMind/Anthropic/DeepSeek/智谱等）</li><li>综述/知乎专栏/微信公众号（优质作者）</li><li>社区：Hacker News、Reddit r/MachineLearning、掘金</li></ul><h2 id="五、开源-动手" tabindex="-1">五、开源（动手） <a class="header-anchor" href="#五、开源-动手" aria-label="Permalink to &quot;五、开源（动手）&quot;">​</a></h2><ul><li>** transformers / vLLM / llama.cpp**：读源码学工程</li><li><strong>LangChain / LlamaIndex</strong>：学 Agent/RAG 范式（也看其局限）</li><li><strong>tiny-llm / nanoGPT</strong>：从零训小模型，理解全链路</li><li>自己复现：MHA、RoPE、LoRA、DPO 训练 loop</li></ul><h2 id="六、学习节奏建议" tabindex="-1">六、学习节奏建议 <a class="header-anchor" href="#六、学习节奏建议" aria-label="Permalink to &quot;六、学习节奏建议&quot;">​</a></h2><ul><li>70% 核心知识（L0/L1/L2）、20% 项目、10% 前沿</li><li>每日 2h 持续 &gt; 周末突击</li><li>每学一模块：笔记 + 代码 + 一篇博客/产出</li></ul><h2 id="七、高频追问" tabindex="-1">七、高频追问 <a class="header-anchor" href="#七、高频追问" aria-label="Permalink to &quot;七、高频追问&quot;">​</a></h2><p><strong>Q：论文读不完怎么办？</strong></p><blockquote><p>不追求读完，追「重要 + 与你方向相关」的。先读经典打底，再按需读新论文；用「摘要+图+实验」快读法，思想到位即可。</p></blockquote><p><strong>Q：要不要从零训模型？</strong></p><blockquote><p>强烈建议至少一次（tiny 模型）：从数据→训练→推理跑通，比读十篇论文更懂底层。nanoGPT/tiny-llm 是好起点。</p></blockquote><hr><p>➡️ 下一步：<a href="./05-薪资爆料与行业洞察">05-薪资爆料与行业洞察</a></p>',22)])])}const g=l(i,[["render",r]]);export{p as __pageData,g as default};
